// Generated by `just generate` from `src/plugins/dotclaude/slices/asks/domain/writes.ts`. Edit the source and run `just generate`.
// The ask for a `Bash` write to a protected file (task 29.9), as pure functions.
// A protected file is a test file, a limits file, or a file of a kind of `pathKind`: the same set as the `Edit` and `Write` checks.
// For a settings file and a recipe file, the `Edit` check looks at a changed key or recipe. A command shows no such change, so any write to the file asks.
// The write forms are in `limits.ts`. The shell reader is `lib/shell.ts`, the one that the git check uses.
// For a test file or a limits file, a write that only adds gets no ask, the same as a `Write` of a new file:
// a redirect `>>`, `tee -a`, and a form that creates (`>`, `tee`, `cp`, `install`, `ln -f`, the destination of `mv`) onto a file that does not exist.
// A path-only kind (lint config, runner config, CI file, hook file, settings file, recipe file) asks for any write, as `Edit` does.
// A path outside the project root, under `~`, `$HOME`, or `${HOME}`, gets only the checks from the path alone:
// a lint config, a runner config, a CI file, a hook file (`~/.claude/hooks/`), a settings file, and a recipe file.
// The test-path rule and the limits-name rule do not apply there, because such a file is not a file of the project.
// A target under `/dev` or under a variable other than `CLAUDE_PROJECT_DIR` or `HOME` gets no ask.
// Limits: the check does not follow a `cd`, so a path is relative to the project root.
// A path with a variable (`$F`) or a glob (`*`, `?`, `[a-z]`, `{a,b}`) is read by its literal part: each variable and glob counts as the name `x`.
// It asks only when the literal part is a protected path (`tests/*.test.mjs`) and passes `$F` or `src/*.mjs`.
// A command over the scan bound (`SHELL_SCAN_MAX_CHARS`) gets no write ask here, and the existing behavior applies.

import {
  ITEMS_SHOWN_MAX,
  LIMIT_FILE_NAME,
  RECIPE_FILE_NAMES,
} from "../limits.ts";
import { codeCommands, codeWords } from "./code.ts";
import { targets } from "./forms.ts";
import { namedByHooks } from "./hooks.ts";
import { isTestPath, pathKind, riskOf } from "./kinds.ts";
import { isAbsolute, normalize, relative, resolve } from "./paths.ts";
import { type Scripts, withScripts } from "./scripts.ts";
import type { Reader } from "./text.ts";

const VARIABLE = /\$\{[^}]*\}|\$[A-Za-z_]\w*|\$[@*#?!$-]|`[^`]*`/g;
const GLOB = /\[[^\]]*\]|\{[^}]*\}|[*?]/g;
const PROJECT_VARIABLE =
  /^(?:\$\{CLAUDE_PROJECT_DIR\}|\$CLAUDE_PROJECT_DIR)(?=\/|$)/;
const HOME_PREFIX = /^(?:~|\$HOME|\$\{HOME\})\//;

/** A write of a command or of a script: the `form` that writes it, the `word` that names the path, and how it writes. */
type Write = {
  form: string;
  word?: string;
  folders?: boolean;
  mode?: string;
  pathOnly?: boolean;
  needsExist?: boolean;
};

/** Where a write points: the path `rel` from the project root, and the flags of `locate`. */
type Located = { rel: string; open: boolean; shown: string; outside: boolean };

/** The label of the protected kind of `rel`, or undefined. With `pathOnly`, the test-path rule and the limits-name rule do not apply, and no `hooks.json` is read. */
const kindOf = async (
  rel: string,
  root: string,
  read: Reader,
  pathOnly: boolean,
): Promise<string | undefined> => {
  const parts = rel.split("/");
  const name = parts.at(-1) as string;
  const kind = pathKind(
    rel,
    !pathOnly && (await namedByHooks(rel, root, read)),
  );
  if (kind) return kind;
  if (parts.at(-2) === ".claude" && /^settings.*\.json$/.test(name))
    return "a settings file";
  if (RECIPE_FILE_NAMES.test(name)) return "a build file with a check recipe";
  if (pathOnly) return undefined;
  if (isTestPath(rel)) return "a test file";
  return LIMIT_FILE_NAME.test(name) ? "a limits file" : undefined;
};

/** The path of `word` from the project root, with each variable and glob read as the name `x` when `literal` is false. */
const resolved = (word: string, root: string, literal: boolean): string => {
  const w = literal ? word : word.replace(VARIABLE, "x").replace(GLOB, "x");
  return relative(root, resolve(root, w));
};

/** `word` with each variable and glob read as the name `x`. */
const literalOf = (word: string): string =>
  word.replace(VARIABLE, "x").replace(GLOB, "x");

/**
 * Where `word` points, as `{ rel, open, shown, outside }`, or undefined when the check skips it.
 * `rel` is the path from the project root, with each variable and glob read as `x`, and `open` is true when `word` had one.
 * `outside` is true for a path under `~`, `$HOME`, or `${HOME}` (`rel` starts with `home/`), or outside the project root (`rel` is the absolute path without its first `/`).
 * The check skips a target under `/dev` and under a variable other than `CLAUDE_PROJECT_DIR` or `HOME`.
 */
const locate = (word: string, root: string): Located | undefined => {
  if (word.startsWith("/dev/")) return undefined;
  if (HOME_PREFIX.test(word)) {
    const rest = word.replace(HOME_PREFIX, "");
    const rel = normalize(`/home/${literalOf(rest)}`).slice(1);
    return { rel, open: literalOf(rest) !== rest, shown: word, outside: true };
  }
  const w = word.replace(PROJECT_VARIABLE, root);
  if (/^[~$`]/.test(w)) return undefined;
  const rel = resolved(w, root, false);
  const open = rel !== resolved(w, root, true);
  if (rel === ".." || rel.startsWith("../") || isAbsolute(rel))
    return {
      rel: resolve(root, literalOf(w)).slice(1),
      open,
      shown: word,
      outside: true,
    };
  return { rel, open, shown: open ? word : rel, outside: false };
};

/** The form of a path that code in another language names. */
const SCRIPT_FORM = "a script";

/** True when the write only adds to a test file or a limits file, so it gets no ask. A path-only kind always asks. */
const adds = (
  kind: string,
  mode: string | undefined,
  exists: boolean,
): boolean => {
  if (kind !== "a test file" && kind !== "a limits file") return false;
  return mode === "append" || (mode === "create" && !exists);
};

/**
 * The ask reasons for the writes in `command`. A list of strings, empty when no write form has a protected target.
 * `scripts` are the texts of the script files that the command runs (`scriptTexts`).
 */
export const shellWriteReasons = async (
  command: string,
  root: string,
  read: Reader,
  scripts: Scripts,
): Promise<string[]> => {
  const { commands, redirects, code, fileCode, truncated } = withScripts(
    command,
    scripts,
  );
  if (truncated) return [];
  const found: Write[] = [
    // Code in another language can write any path that it names, with a shell command or with its own file API.
    ...code
      .flatMap(codeWords)
      .map((word) => ({ form: SCRIPT_FORM, word, mode: "script" })),
    ...[...code, ...fileCode].flatMap(codeCommands).flatMap(targets),
    ...redirects.map(({ op, target }) => ({
      form: op,
      word: target,
      mode: op.endsWith(">>") ? "append" : "create",
    })),
    ...commands.flatMap(targets),
  ];
  const out = new Map<string, string>();
  for (const { form, word, folders, mode, pathOnly, needsExist } of found) {
    if (word === undefined || word === "") continue;
    const at = locate(word, root);
    if (!at) continue;
    const { rel, open, shown, outside } = at;
    const only = outside || pathOnly === true;
    const kind =
      (await kindOf(rel, root, read, only)) ??
      (folders ? await kindOf(`${rel}/x`, root, read, only) : undefined);
    if (!kind) continue;
    if (needsExist && (await read(`${root}/${rel}`)) === null) continue;
    if (
      adds(
        kind,
        mode,
        folders || open ? true : (await read(`${root}/${rel}`)) !== null,
      )
    )
      continue;
    const what =
      form === SCRIPT_FORM
        ? `A script that a program other than the shell runs names the path \`${shown}\`.
The check cannot read a script in another language, so it treats each path that the script names as a write.`
        : `The command form \`${form}\` writes the path \`${shown}\`.`;
    out.set(
      `${form} ${word}`,
      `${what}
The path is ${kind}.${open ? "\nThe path has a variable or a glob, so the check reads only its literal part." : ""}
${riskOf(kind)}`,
    );
  }
  return [...out.values()].slice(0, ITEMS_SHOWN_MAX);
};
